import{_ as n,l as i,o as e,c as l,v as t,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"排序网络","description":"","frontmatter":{"title":"排序网络","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sorting-networks.md","filePath":"cs/sorting-networks.md","lastUpdated":1789023840000}'),p={name:"cs/sorting-networks.md"};function _(m,a,A,u,g,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="排序网络" tabindex="-1">排序网络 <a class="header-anchor" href="#排序网络" aria-label="Permalink to &quot;排序网络&quot;">​</a></h1><div class="epigraph"><p>比较器只交换两条线，数据无关控制；Batcher 双调 $O(\\log^2 n)$ 层，Ajtai–Komlós–Szemerédi $O(\\log n)$ 层存在但巨大。</p><footer>—— 据 Batcher, Sorting Networks and Their Applications, 1968；Ajtai, Komlós and Szemerédi, 1983；Knuth TAOCP 卷 3 整理</footer></div><p>上一课<a href="/cs/work-span-model">work-span</a>是任务 DAG。排序网络：固定线路，每层并行比较。缺口是 0-1 原理与 Batcher。不重写快排期望。后课对手论证比较下界。Knuth 卷 3 是比较网络标准出处。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>比较器 \\((i,j)\\)：若 \\(x_i\\gt x_j\\) 则交换。网络对任意输入正确 \\(\\Leftrightarrow\\) 对 0-1 输入正确（0-1 原理）。Batcher：奇偶归并、双调排序，\\(O(\\log^2 n)\\) 层、\\(O(n\\log^2 n)\\) 比较器。AKS：\\(O(\\log n)\\) 层，常数巨大。实践 Batcher 或 bitonic GPU。</p><p>缺口是无数据依赖控制，不是堆排序。</p><h3 id="不是比较次数-下界的紧实现" tabindex="-1">不是比较次数 \\(n\\log n\\) 下界的紧实现 <a class="header-anchor" href="#不是比较次数-下界的紧实现" aria-label="Permalink to &quot;不是比较次数 $n\\log n$ 下界的紧实现&quot;">​</a></h3><p>信息下界 \\(\\Omega(n\\log n)\\) 比较；网络深度另计。AKS 深度 \\(O(\\log n)\\) 达到并行最优量级，常数不实用。</p><p><span class="marginnote">Batcher 1968。AKS 1983。Knuth TAOCP 卷 3。后课对手论证 \\(\\Omega(n\\log n)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画线。证明用 0-1。构造双调归并递归。计数层数。</p>',11)),(e(),s(c,null,{default:r(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22n%20%E6%9D%A1%E7%BA%BF%22%5D%20--%3E%20CMP%5B%22%E5%9B%BA%E5%AE%9A%E6%AF%94%E8%BE%83%E5%99%A8%E5%B1%82%22%5D%0A%20%20CMP%20--%3E%20OUT%5B%22%E6%9C%89%E5%BA%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>插入网络 \\(O(n^2)\\) 层，仅教学。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>0-1 原理：任意单调可分的错误会在 0-1 上显现。双调序列归并可递归拆半。与工作跨度：一层 = 一步跨度，工作 = 比较器总数。与 PRAM：网络是更弱、更规则的并行。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画 AKS expander。不写量子排序。后课默认：实用排序网络 Batcher \\(O(\\log^2 n)\\) 层。下一课对手论证。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据无关比较器网络。</li><li>0-1 原理；Batcher \\(O(\\log^2 n)\\) 层。</li><li>AKS 渐近更深优、常数大。</li><li>出处：Batcher, 1968；AKS, 1983；Knuth TAOCP 卷 3。</li></ul>',7))])}const T=n(p,[["render",_]]);export{P as __pageData,T as default};
